export const roles: readonly ['main', 'manager', 'specialist', 'evaluator'];
export const providers: readonly ['ollama', 'claude'];
export const MODELS_PATH: '/api/models';
export type ModelChoice = { id: string; provider: 'ollama' | 'claude' | 'lmstudio' | 'subscription'; label: string; size: string };
export const memoryTypes: readonly ['fact', 'event', 'context', 'insight', 'preference', 'skill', 'relationship', 'task'];
export const drawerKinds: readonly ['owner', 'experience', 'project', 'task', 'people'];
export const traitNames: readonly ['doubt', 'caution', 'creativity', 'thoroughness', 'independence', 'verbosity', 'warmth', 'curiosity', 'persistence'];
export const MAX_MEMORY: number;
export type DrawerKind = (typeof drawerKinds)[number];
export type MemoryType = (typeof memoryTypes)[number];
export type TraitName = (typeof traitNames)[number];
export type Traits = Record<TraitName, number>;
export type Drawer = { kind: DrawerKind; key?: string };
export function validDrawer(d: unknown): d is Drawer;
export function cardPath(path: string): { kind: string; agent?: string; id?: string } | null;
export function cardRoute(path: string): boolean;
export function validProfileEdit(b: unknown): boolean;
export function allowedAgentCard(method: string, path: string, body?: unknown): boolean;
export type Persona = { version: number; traits: Traits; preset: string | null; dialect: string; locked: boolean; note: string | null; source: string; createdAt: string | null };
export type PersonaCurrent = Persona & { traitNames: TraitName[]; dialects: string[]; presets: { id: string; label: string; traits: Traits }[] };
export type MemoryItem = { id: string; type: MemoryType; content: string; importance: number; drawer: Drawer; layer: string | null; createdAt: string; tags: string[] };
export type MemoryVersion = { version: number; change: string; type: string; content: string; createdAt: string; reason: string };
export function memoryItem(x: unknown): MemoryItem;
export function agentCardResponse(path: string, status: number, body: unknown): unknown;
